xhtml:div.style:
width:500px;
height:360px;
box-sizing:border-box;
padding:30px;
background:#f7f7f7;
font-family:Arial,sans-serif;

width:340px;
margin:auto;
margin-top:70px;
padding:25px;
box-sizing:border-box;
background:white;
border:2px dashed #007BFF;
border-radius:10px;
text-align:center;

xhtml:button.style:
margin-top:15px;
padding:10px 22px;
border:0;
border-radius:5px;
background:#007BFF;
color:white;
cursor:pointer;
font-size:15px;

svg.script:
const fileInput =
    document.getElementById("file");

const runButton =
    document.getElementById("run");

const status =
    document.getElementById("status");

let selectedFile = null;


fileInput.addEventListener("change", function () {

    selectedFile = fileInput.files[0];

    if (!selectedFile) {
        status.textContent =
            "Select an HTML file";
        return;
    }

    status.textContent =
        "Selected: " + selectedFile.name;
});


runButton.addEventListener("click", function () {

    if (!selectedFile) {
        alert("Select an HTML file first.");
        return;
    }


    /*
     * Do NOT parse the HTML ourselves.
     *
     * Do NOT put it into SVG.innerHTML.
     *
     * Give the browser the HTML file as an actual
     * top-level HTML document instead.
     */

    const htmlURL =
        URL.createObjectURL(selectedFile);


    /*
     * Replace the SVG in the current tab.
     */
    window.location.replace(htmlURL);


    /*
     * Do not revoke the URL here.
     *
     * The browser needs it to load the new document.
     */
});
